import pandas as pd
from decimal import Decimal, ROUND_HALF_UP

def xl_round(x, digits):
    q = Decimal(1).scaleb(-digits)
    return float(Decimal(str(x)).quantize(q, rounding=ROUND_HALF_UP))

d = pd.DataFrame({
    "Channel": ["Email", "Email", "Ads", "Ads", "Ads"],
    "Orders": [3, 5, 1, 0, 7],
    "Visits": [40, 0, 16, 25, 90],
})
d["Rate"] = [0 if v == 0 else xl_round(o / v * 100, 1) for o, v in zip(d["Orders"], d["Visits"])]
print(d.groupby("Channel")["Rate"].sum().round(1).to_string())
